# Isolated illustrative experiment; never imports game source.
world_rates=[]; allcounts=Counter(); count_distribution=Counter()
for seed in range(100):
 rng=random.Random(seed); c=Counter()
 for _ in range(1000):
  n=1+rng.randrange(2);count_distribution[n]+=1
  seen=set()
  for __ in range(n):
   pick=rng.choices(FAMILIES,weights=[x[1] for x in FAMILIES],k=1)[0]
   seen.add(pick[0])
  for family in seen:
   c[family]+=1;allcounts[family]+=1
 world_rates.append(c)
obs=[]
for f,w in FAMILIES:
 vals=sorted(c[f]/10 for c in world_rates)
 obs.append({'family':f,'selectionWeight':w,'artificialAdultsWithFamilyPercent':round(allcounts[f]/1000,3),'across100ArtificialWorlds5to95Percent':[round(vals[4],2),round(vals[94],2)]})
